def comb_sort(nums):
    n = len(nums)
    gap = n
    shrink_factor = 1.3
    sorted_list = nums.copy()  # To avoid modifying the original list

    while gap > 1 or not is_sorted(sorted_list):
        gap = max(1, gap // shrink_factor)

        i = 0
        while i + gap < len(sorted_list):
            if sorted_list[i] > sorted_list[i + gap]:
                sorted_list[i], sorted_list[i + gap] = sorted_list[i + gap], sorted_list[i]
            i += 1

    return sorted_list

def is_sorted(nums):
    for i in range(len(nums) - 1):
        if nums[i] > nums[i + 1]:
            return False
    return True
