def get_median(arr1, arr2, n):
    merged = []
    i = j = 0

    # Merge the two sorted arrays
    while i < n and j < n:
        if arr1[i] <= arr2[j]:
            merged.append(arr1[i])
            i += 1
        else:
            merged.append(arr2[j])
            j += 1

    # Remaining elements of arr1 or arr2
    while i < n:
        merged.append(arr1[i])
        i += 1

    while j < n:
        merged.append(arr2[j])
        j += 1

    # Calculate the median
    if n % 2 == 0:
        median = (merged[n // 2 - 1] + merged[n // 2]) / 2.0
    else:
        median = merged[n // 2]

    return median
